def _parse_attrs(options: Dict[str, Any]) -> Dict[str, Any]:
    attrs = {}
    if 'alt' in options:
        attrs['alt'] = options['alt']
    if 'target' in options:
        attrs['target'] = options['target']

    for key in ['width', 'height']:
        if key in options:
            value = options[key]
            match = _num_re.match(value)
            if match:
                attrs[key] = value

    if 'align' in options:
        align = options['align']
        if align in _allowed_aligns:
            attrs['align'] = align

    return attrs


def render_block_image(self: 'HTMLRenderer', src: str, alt: Optional[str] = None, width: Optional[str] = None, height: Optional[str] = None, **attrs: Any) -> str:
    src = escape_url(src)
    alt = escape_text(alt) if alt else ''

    html = '<img src="' + src + '" alt="' + alt + '"'

    if width:
        html += ' width="' + escape_text(width) + '"'
    if height:
        html += ' height="' + escape_text(height) + '"'

    if 'target' in attrs:
        html += ' data-target="' + escape_text(attrs['target']) + '"'
    if 'align' in attrs:
        html += ' align="' + escape_text(attrs['align']) + '"'

    html += ' />'
    return html


def render_figure(self: Any, text: str, align: Optional[str] = None, figwidth: Optional[str] = None, figclass: Optional[str] = None) -> str:
    html = '<figure'

    if align:
        html += ' align="' + escape_text(align) + '"'
    if figwidth:
        html += ' style="width:' + escape_text(figwidth) + '"'
    if figclass:
        html += ' class="' + escape_text(figclass) + '"'

    html += '>\n' + text + '\n</figure>\n'
    return html


def render_figcaption(self: Any, text: str) -> str:
    return '<figcaption>\n' + text + '</figcaption>\n'


def render_legend(self: Any, text: str) -> str:
    return '<div class="legend">\n' + text + '</div>\n'


def parse_directive_content(self, block: 'BlockParser', m: Match[str], state: 'BlockState') -> Optional[List[Dict[str, Any]]]:
    content = self.parse_content(m)
    if not content:
        return None

    tokens = list(self.parse_tokens(block, content, state))
    if not tokens:
        return None
    caption = tokens[0]
    if caption['type'] == 'paragraph':
        caption['type'] = 'figcaption'
        children = [caption]
        if len(tokens) > 1:
            children.append({
                'type': 'legend',
                'children': tokens[1:]
            })
        return children
    return None


def parse(self, block: 'BlockParser', m: Match[str], state: 'BlockState') -> Dict[str, Any]:
    options = dict(self.parse_options(m))
    image_attrs = _parse_attrs(options)
    image_attrs['src'] = self.parse_title(m)

    align = image_attrs.pop('align', None)
    fig_attrs = {}
    if align:
        fig_attrs['align'] = align
    for k in ['figwidth', 'figclass']:
        if k in options:
            fig_attrs[k] = options[k]

    children = [{'type': 'block_image', 'attrs': image_attrs}]
    content = self.parse_directive_content(block, m, state)
    if content:
        children.extend(content)
    return {
        'type': 'figure',
        'attrs': fig_attrs,
        'children': children,
    }


def __call__(self, directive: 'BaseDirective', md: 'Markdown') -> None:
    directive.register(self.NAME, self.parse)

    assert md.renderer is not None
    if md.renderer.NAME == 'html':
        md.renderer.register('figure', render_figure)
        md.renderer.register('block_image', render_block_image)
        md.renderer.register('figcaption', render_figcaption)
        md.renderer.register('legend', render_legend)
